import{d as h,C as e,o as g,c as d,j as n,a,E as o,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const z=JSON.parse('{"title":"中庸·第13章","description":"《中庸》第 13 章——道不远人：忠恕违道不远，施诸己而不愿亦勿施于人；君子之道四，丘未能一。","frontmatter":{"title":"中庸·第13章","description":"《中庸》第 13 章——道不远人：忠恕违道不远，施诸己而不愿亦勿施于人；君子之道四，丘未能一。","category":"guide","aliases":["第13章","中庸第13章","道不远人"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-13.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-13.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-13.md"},b=h({...m,setup(p){const r=[{id:"buyuanr",label:"道不远人 · 以人治人",showLabel:!0,sentences:[["子曰：“道不远人。人之为道而远人，不可以为道。《诗》云：‘",{text:"伐柯",glossary:"fake"},"伐柯，其则不远。’执柯以伐柯，",{text:"睨",glossary:"ni"},"而视之，犹以为远。故君子",{text:"以人治人",glossary:"yirenzhiren"},"，",{text:"改而止",glossary:"gaierzhi"},"。"]],note:"「道不远人」——道并不远离人。「人之为道而远人，不可以为道」：若把道弄得远离人生，便不成其为道。引《诗》「伐柯伐柯，其则不远」——砍斧柄，样板就在手里；「执柯以伐柯，睨而视之，犹以为远」——拿着斧柄去砍斧柄，斜眼一瞥还嫌远。所以「君子以人治人，改而止」：以人的常道治人，改了便止。"},{id:"zhongshu",label:"忠恕违道不远 · 施诸己而不愿亦勿施于人",showLabel:!0,sentences:[[{text:"忠恕",glossary:"zhongshu"},{text:"违道不远",glossary:"weidao"},"，",{text:"施诸己而不愿",glossary:"shizhuji"},"，亦勿施于人。"]],note:"「忠恕违道不远」——尽己之谓忠，推己之谓恕，能忠能恕，离道就不远了。「施诸己而不愿，亦勿施于人」——加在自己身上不愿接受的，就不要加给别人。这是「恕」的正面界说。"},{id:"sidao",label:"君子之道四 · 庸德之行，言顾行",showLabel:!0,sentences:[["君子之道四，",{text:"丘",glossary:"qiu"},"未能一焉：所求乎子，以事父未能也；所求乎臣，以事君未能也；所求乎弟，以事兄未能也；所求乎朋友，先施之未能也。"],["庸德之行，庸言之谨，有所不足，不敢不勉，有余不敢尽；言顾行，行顾言，君子胡不",{text:"慥慥",glossary:"zaozao"},"尔！”"]],note:"孔子自责：「君子之道四，丘未能一焉」——君子之道有四条，我一条都没能做到：要求儿子事父，自己事父未能；要求臣事君，自己事君未能；要求弟事兄，自己事兄未能；要求朋友先施，自己先施未能。接着说「庸德之行，庸言之谨」：平常的德行要实行，平常的言语要谨慎；有所不足不敢不勉力，有余也不敢尽用；「言顾行，行顾言」——言顾及行、行顾及言，君子怎能不「慥慥」（笃实忠厚）呢！"}],t=[{id:"fake",term:"伐柯",pinyin:"fá kē",meaning:"砍制斧柄。柯：斧柄。《诗·豳风·伐柯》：「伐柯如之何？匪斧不克。」"},{id:"ni",term:"睨",pinyin:"nì",meaning:"斜视。朱注：「睨，邪视也。」执柯伐柯、睨而视之犹以为远——喻人总把道看得太远。"},{id:"yirenzhiren",term:"以人治人",pinyin:"yǐ rén zhì rén",meaning:"朱注：「即以其人之道，还治其人之身。」以人所本有、能知能行之道来要求他。"},{id:"gaierzhi",term:"改而止",pinyin:"gǎi ér zhǐ",meaning:"改了就不再追究。朱注：「其人能改，即止不治。」"},{id:"zhongshu",term:"忠恕",pinyin:"zhōng shù",meaning:"朱注：「尽己之心为忠，推己及人为恕。」"},{id:"weidao",term:"违道不远",pinyin:"wéi dào bù yuǎn",meaning:"离道不远。违：去、离，不是「违背」。"},{id:"shizhuji",term:"施诸己而不愿",pinyin:"shī zhū jǐ ér bù yuàn",meaning:"加在自己身上而不愿意的（事）。此即忠恕之事，与《论语》「己所不欲，勿施于人」同旨。"},{id:"qiu",term:"丘",pinyin:"qiū",meaning:"孔子自称其名。孔子名丘。"},{id:"zaozao",term:"慥慥",pinyin:"zào zào",meaning:"笃实的样子。朱注：「慥慥，笃实貌。」"}];return(y,i)=>{const s=e("DaoTextReading"),l=e("DaoKeywordCards");return g(),d("div",null,[i[0]||(i[0]=n("h1",{id:"中庸·第13章",tabindex:"-1"},[a("中庸·第13章 "),n("a",{class:"header-anchor",href:"#中庸·第13章","aria-label":'Permalink to "中庸·第13章"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),n("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),i[2]||(i[2]=n("p",null,"第十三章说「道不远人」：道就在人身上，所以「以人治人」、以忠恕相待；末段列出「君子之道四」，孔子自谓一条也没做到。默认竹简沉浸通读；切「经典阅读」可点生词。",-1)),o(s,{colophon:"道不远人 · 忠恕 · 君子之道四",tone:"ink",sections:r,glossary:t,"default-mode":"slips","aria-label":"中庸·第13章 原文"}),i[3]||(i[3]=n("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),n("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),o(l,{items:[{term:"伐柯",pinyin:["fá","kē"],meaning:"砍制斧柄。柯：斧柄。手执斧柄去砍斧柄，其法则就在手里。"},{term:"睨",pinyin:["nì"],meaning:"斜视。睨而视之犹以为远——喻人总把道看得太远。"},{term:"以人治人",pinyin:["yǐ","rén","zhì","rén"],meaning:"朱注：「即以其人之道，还治其人之身。」"},{term:"改而止",pinyin:["gǎi","ér","zhǐ"],meaning:"改了就不再追究。"},{term:"忠恕",pinyin:["zhōng","shù"],meaning:"尽己之心为忠，推己及人为恕。"},{term:"慥慥",pinyin:["zào","zào"],meaning:"笃实的样子。"}]}),i[4]||(i[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>道不远人 · 以人治人</strong>：孔子说：「道并不远离人。人若以为道远离人，那便不可以为道了。《诗经》说：『伐柯伐柯，其则不远。』手拿斧柄去砍斧柄，斜眼看它，还觉得远。所以君子以人之道治人，改了就不再追究。」</p><p><strong>忠恕违道不远</strong>：忠恕离道不远：加在自己身上而不愿的，也不要加到别人身上。</p><p><strong>君子之道四 · 庸德之行</strong>：君子的道有四条，我孔丘一条也没做到：要求儿子对己的孝，用以事父，没能做到；要求臣对己的忠，用以事君，没能做到；要求弟弟对己的悌，用以事兄，没能做到；要求朋友对己的信，先施于人，没能做到。平常的德行去实践，平常的言语要谨慎；有所不足不敢不勉力，有余也不敢用尽；说话顾到行动，行动顾到说话——君子怎能不笃笃实实呢！</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第十三章三节，层层落近：</p><ol><li><strong>道不远人</strong>：道不在远处，就在人身上；所以「以人治人」（即以人之道还治其人），「改而止」</li><li><strong>忠恕</strong>：离道不远——「施诸己而不愿，亦勿施于人」</li><li><strong>君子之道四</strong>：孝、忠、悌、信四条，孔子自谓「未能一」，末以「言顾行，行顾言」作结</li></ol><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「道不远人」承接上一章</strong>：第 12 章说「夫妇之愚，可以与知能行」，本章把这句话坐实——道就在人身上，所以<strong>凡己之所以责人者，皆道之当然</strong>（朱注），反过来自责自修即可。</li><li><strong>「以人治人，改而止」是一句极见分寸的话</strong>：要求别人，用他自己也知道的道理；而且<strong>改了就停</strong>。这不是放任，是知道分寸——不借道理追人到底。</li><li><strong>「君子之道四」是自省的四把尺</strong>：孔子把「我要求别人的」逐条拿来量自己（求子事父、求臣事君、求弟事兄、求朋友先施），结果一条也没做到。这是「以责人之心责己」的具体做法。</li><li><strong>忠恕是最低也最高的标准</strong>：不高深，但每件事上都成立。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>反求四问</strong>：我用什么标准要求别人？同样的标准，我用在自己身上了吗？</li><li><strong>改而止</strong>：责备的目的是「改」，改了就该停——不停，就变成了别的东西。</li><li><strong>忠恕自查</strong>：今天有没有把自己不愿的，加到别人身上？</li><li><strong>言顾行，行顾言</strong>：说话的尺度对着行动的尺度——这句话可以作为每日自检。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>孔子说：道并不远离人。你若以为道在很远的地方，那就错了——<strong>手拿斧柄砍斧柄，法度就在手里</strong>，可人还是觉得远。真正的做法是「以人治人」：用他自己也懂的道理去要求他，改了就不再追究。</p><p>接着给出最低也最高的标准：<strong>忠恕</strong>——自己不愿的，不要加给别人。 最后是四把自省的尺：要求儿子孝顺我，那么我对父亲做到了吗？要求下属尽忠，我对上级做到了吗？要求弟弟恭敬，我对兄长做到了吗？要求朋友先待我好，我先待他了吗？孔子说：<strong>一条我也没做到。</strong></p><p>所以这一章的重点不是「要求」，而是<strong>把要求掉转过来对着自己</strong>。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「以人治人，改而止」——我要求别人时，用的是不是他自己也懂的道理？他改了之后，我停了吗？</li><li>「君子之道四」——用「要求别人的标准」逐条量自己（事父、事君、事兄、先施朋友），哪一条差得最多？</li><li>「忠恕」——今天有没有把自己不愿的，加到了别人身上？</li><li>「言顾行，行顾言」——我的话与行动，尺度一致吗？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-12">中庸·第12章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-14">中庸·第14章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',23))])}}});export{z as __pageData,b as default};
